import {configureData,dataPageView,bindDataPage,openImporter} from './data-page.js';
import * as repository from './project-repository.js';

import {projectSetup} from './project-setup.js';

import {mountMap} from './project-map.js';

import {overviewView,switcherView,bindSwitcher,allowedTool,seismicStages,workflows} from './project-overview.js';

import {directoryView, cardView, insightsView} from './projects-view.js';

import {session, initializeAuth, storageKey, localGet, logout, hasActionLink, api} from './auth.js';

import {renderAccount} from './auth-ui.js';

import {publicHeader as publicHeaderView, renderLanding as renderLandingView, footer, bindPublic, accountMenu} from './public.js';

import {legalDocuments, legalPage} from './legal-pages.js';

import {specialist} from './workbenches.js';

import {modules,stages} from './catalog.js';

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',data:'M4 4h16v16H4z M4 9h16 M9 9v11',map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 3v15 M15 6v15',logs:'M4 3v18 M12 3v18 M20 3v18 M4 6l3 3-2 3 3 3-4 3 M12 5l4 4-3 4 3 4-4 2',models:'m12 3 9 5-9 5-9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',decisions:'M12 3v18 M5 7l7-4 7 4 M5 17l7 4 7-4 M3 12h18',reports:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',search:'m20 20-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',plus:'M12 4v16 M4 12h16',arrow:'M5 12h14 m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',upload:'M12 16V3 m-5 5 5-5 5 5 M4 15v6h16v-6',file:'M5 3h10l4 4v14H5z M14 3v5h5',close:'m6 6 12 12 M18 6 6 18',layers:'m12 3 9 5-9 5-9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',menu:'M4 6h16 M4 12h16 M4 18h16',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5z M10 21h4',download:'M12 3v13 m-5-5 5 5 5-5 M4 17v4h16v-4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',pin:'M12 21s7-7 7-12a7 7 0 0 0-14 0c0 5 7 12 7 12 M12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z',help:'M9 8a3 3 0 1 1 5 3c-2 1-2 2-2 3 M12 17h.01 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20'};

paths.star='m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z';paths.trash='M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7';

const icon=(n)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.logs}"/></svg>`;

const btn=(text,action,primary=false)=>`<button type="button" ${primary?'class="primary"':''} data-action="${action}">${text}</button>`;

const go=(id,text,primary=false)=>`<button type="button" ${primary?'class="primary"':''} data-go="${id}" aria-label="${text.includes('svg')?esc(modules.find(m=>m.id===id)?.name||stages.find(s=>s[0]===id)?.[1]||id):esc(text)}">${text}</button>`;

const badge=(text,color='green')=>`<span class="badge ${color}"><span class="dot"></span>${esc(text)}</span>`;

const demoWells=[];

const initial={project:'',well:'',tab:'files',basemap:'Terrain',layers:{},opacity:75,mapZoom:1,mapSelected:null,measurement:null,measurePoints:[],filters:'All',qcRecipe:'',qcDecision:null,qcPreview:false,scenario:'',configs:{},audit:[],files:[],cutoffs:{},reviews:[],savedLayouts:[],projects:[],theme:'Light'};

let state;try{state={...structuredClone(initial),...JSON.parse((storageKey('stratax.frontend.v1')&&localGet(storageKey('stratax.frontend.v1')))||'{}')};}catch{state=structuredClone(initial);}

let portfolio={records:[],activeId:null,contexts:{}};

portfolio.contexts=portfolio.contexts||{};if(portfolio.contexts[portfolio.activeId])state={...structuredClone(initial),...portfolio.contexts[portfolio.activeId]};

let wells=[];

let projectQuery='',projectFilter='Active',projectView='grid',projectSort='recent';

function persistPortfolio(){if(!session.user)return;try{localStorage.setItem(storageKey('stratax.projects.v2'),JSON.stringify(portfolio));}catch{toast('Device recovery cache is full. Your chosen project destination will still be saved.');}queueProjectSaves();}

function projectContext(){return portfolio.records.find(p=>p.id===portfolio.activeId);}

let fieldIndex=0;

let route=location.hash.slice(1)||'home',search='',formTab='Workbench';

const save=()=>{if(!session.user||!portfolio.activeId)return;portfolio.contexts[portfolio.activeId]=structuredClone(state);const p=projectContext();if(p)p.updatedAt=new Date().toISOString();try{persistPortfolio();}catch{toast('Device recovery storage is full. Save or download your project.');}};

function log(action){state.audit.unshift({action,time:new Date().toISOString(),well:state.well});save();}

function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('show'),3600);}

function navigate(id){route=id;search='';formTab='Workbench';location.hash=id;render();window.scrollTo(0,0);}

const panel=(title,content,action='',subtitle='')=>`<section class="panel"><header class="panel-head"><div><h2>${title}</h2>${subtitle?`<small>${subtitle}</small>`:''}</div>${action}</header>${content}</section>`;

function heading(title,subtitle,actions='',eyebrow='WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="sub">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}

function selectedNav(){if(['overview','map','data','reports','catalog','settings'].includes(route))return route;if(['files','wells','documents','digitize','collection'].includes(route))return'data';let m=modules.find(x=>x.id===route);if(m?.group==='Modeling'||m?.group==='Engineering'||route==='models')return'models';if(m?.group==='Decisions'||route==='decisions')return'decisions';return'interpretation';}

function render(){if(hasActionLink())route='email-action';if(legalDocuments[route]){document.querySelector('#app').innerHTML=publicHeader()+legalPage(route)+footer();bindPublic();return;}if(!['home','signin','signup','forgot-password','email-action'].includes(route)){if(!session.ready||!session.user?.emailVerified||!session.accepted){renderAccount('signin');return;}}applyPreferences();if(['home','signin','signup','forgot-password','email-action'].includes(route)){renderPublicPage();return;}if(route==='projects'){renderProjects();return;}if(!projectContext()&&route!=='settings'){navigate('projects');return;}if(!allowedTool(route,projectContext(),modules)){route='overview';history.replaceState(null,'','#overview');}fieldIndex=0;let active=selectedNav();let title=modules.find(x=>x.id===route)?.name||({overview:'Overview',data:'Data',interpretation:'Interpretation',models:'Modeling & engineering',decisions:'Decisions',catalog:'Feature inventory',collection:'Data collection',qualitative:'Qualitative interpretation',quantitative:'Quantitative interpretation'}[route]||'Workspace');$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#home" aria-label="StrataX home"><img src="logo.png" alt="StrataX logo"><div>StrataX<small>Subsurface workspace</small></div></a>${switcherView(projectContext(),esc,icon)}<nav class="nav" aria-label="Main navigation"><button data-go="projects">${icon('layers')}All projects</button><div class="label">Workspace</div>${[['overview','Overview','overview'],['data','Data','data'],['map','Map','map'],['interpretation','Interpretation','logs'],['models','Modeling & engineering','models'],['decisions','Decisions','decisions'],['reports','Reports','reports']].filter(([id])=>allowedTool(id,projectContext(),modules)).map(([id,t,i])=>`<button data-go="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}${t}${id==='data'?'<span class="nav-count">'+(currentSampleFiles().length+state.files.length)+'</span>':''}</button>`).join('')}<button data-action="project-settings">${icon('settings')}Project settings</button></nav><div class="sidebar-bottom workspace-utilities"><button data-go="catalog">${icon('layers')}Feature inventory</button><button data-action="help">${icon('help')}Help & shortcuts</button></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><button class="mobile-menu icon" aria-label="Toggle navigation" data-action="menu">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${esc(title)}</strong></div><div class="top-actions"><button class="search-trigger" data-action="search">${icon('search')}<span class="search-label">Search wells, files, tools</span><span class="key">⌘ K</span></button><button class="save-indicator" data-action="save-project">${esc(saveStates.get(portfolio.activeId)||'Saved')}</button><button class="quiet icon" aria-label="Notifications" data-action="notifications">${icon('bell')}</button>${profileMenu()}</div></header><div class="content">${state.downstreamStale&&['quantitative','cutoffs','summaries'].includes(route)?'<div class="note amber" style="margin-bottom:18px">An upstream QC decision changed. Downstream examples require revalidation when calculation services connect.</div>':''}${page()}<footer class="footer"><span>StrataX · Evidence-led subsurface interpretation</span><span>${projectContext()?.storage==='cloud'?'Cloud project':projectContext()?.storage==='local'?'Local folder project':'Download project to save changes'}</span></footer></div></main></div>`;bind();bindProjectUI();}

function page(){if(route==='overview')return overview();if(route==='map')return mapPage();if(['data','collection','files','wells','documents'].includes(route))return dataPage();if(route==='interpretation')return interpretation();if(route==='logs')return logsPage();if(route==='qc')return qcPage();if(route==='qualitative')return hub('Qualitative interpretation','Review geological and fluid indicators against supporting evidence.',modules.filter(m=>m.group==='Qualitative'));if(route==='quantitative')return hub('Quantitative interpretation','Build calibrated property evaluations from reviewed curves.',modules.filter(m=>m.group==='Quantitative'));if(route==='cutoffs')return cutoffsPage();if(route==='summaries')return summaries();if(route==='models')return hub('Modeling & engineering','Extend well evidence into spatial models and engineering studies.',modules.filter(m=>['Modeling','Engineering'].includes(m.group)));if(route==='decisions')return hub('Decisions','Compare scenarios and review candidate opportunities.',modules.filter(m=>m.group==='Decisions'));if(route==='reports')return reports();if(route==='reviews')return reviews();if(route==='settings')return settings();if(route==='catalog')return catalog();let m=modules.find(m=>m.id===route);return m?modulePage(m):overview();}

function overview(){return overviewView({project:projectContext(),workspace:state,stages:projectStages(projectContext()),esc,icon});}

function activityList(n){return state.audit.slice(0,n).map(a=>`<div class="activity"><div>${icon('clock')}</div><div><p>${esc(a.action)}</p><small>${esc(new Date(a.time).toLocaleString())}</small></div></div>`).join('')||'<p class="sub">No saved activity yet.</p>';}

function wellTable(list){return `<div class="table-wrap"><table><thead><tr><th>Well</th><th>Depth / ft MD</th><th>Curves</th><th>Review status</th><th></th></tr></thead><tbody>${list.map(w=>`<tr><td class="well-name">${w.id}</td><td class="mono">${w.depth}</td><td>${w.curves}</td><td>${badge(w.status,w.status==='Reviewed'?'green':'amber')}</td><td><button class="quiet icon" data-well="${w.id}" aria-label="Open ${w.id}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`;}

function mapArt(){return '';}

function mapPage(){const p=projectContext();return heading('Study map','Site coordinates · WGS84',btn('Edit location','project-settings'))+panel('Project location',p.coordinates?'<div id="project-map" class="real-map full-project-map"></div>':'<div class="location-empty"><h3>No location added yet</h3><p>Set your site coordinates in Project settings.</p>'+btn('Add location','project-settings')+'</div>')+'<p class="sub">Only saved site coordinates are displayed. Well and survey geometry require validated source records.</p>'; }

const demoFiles=[];

function currentSampleFiles(){return [];}

function dataPage(){return dataPageView(route);}

function fileTable(files){return `<div class="table-wrap"><table><thead><tr><th>File name</th><th>Category</th><th>Well</th><th>Status</th><th>Size</th><th></th></tr></thead><tbody>${files.length?files.map(f=>`<tr><td>${icon('file')} <span class="well-name">${esc(f.name)}</span></td><td>${esc(f.type)}</td><td>${esc(f.well)}</td><td>${badge(f.status,f.status==='Reviewed'?'green':f.status==='Needs mapping'?'amber':'gray')}</td><td class="mono">${esc(f.size)}</td><td><button data-file="${esc(f.name)}">Review</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No matching files.</td></tr>'}</tbody></table></div>`;}

function cards(list){list=list.filter(m=>allowedTool(m.id,projectContext(),modules));return `<div class="module-grid">${list.map(m=>`<button class="module-card" data-go="${m.id}"><span class="module-icon">${icon(m.group==='Spatial'?'map':m.group==='Modeling'?'models':'logs')}</span><h3>${m.name}</h3><p>${m.description}</p><span class="badge gray">${m.features.length} feature groups</span></button>`).join('')}</div>`;}

function hub(t,d,list){return heading(t,d)+cards(list);}

function interpretation(){return heading('Interpretation workspace','A clear path from reviewed evidence to reservoir evaluation.',go('logs',icon('logs')+'Open log viewer',true))+`<div class="module-grid" style="margin-bottom:22px">${projectStages(projectContext()).map(([id,t,d],i)=>`<button class="module-card" data-go="${id}"><span class="module-icon">${String(i+1).padStart(2,'0')}</span><h3>${t}</h3><p>${d}</p>${badge(!projectContext()?.demo?'Not started':i===0?'Reviewed':i===1?'In review':'Not started',i===0?'green':i===1?'amber':'gray')}</button>`).join('')}</div>${panel('Advanced workspaces',`<div class="panel-body">${cards(modules.filter(m=>m.group==='Advanced'))}</div>`)}`;}

function stepper(id){return `<div class="stepper">${stages.map(([x,t],i)=>`<button data-go="${x}" class="${id===x?'active':''}"><span>0${i+1}</span> ${['Collection','QA/QC','Qualitative','Quantitative','Cutoffs','Summaries'][i]}</button>`).join('')}</div>`;}

function wellSelect(){return `<select id="well-select" aria-label="Selected well">${wells.map(w=>`<option ${w.id===state.well?'selected':''}>${w.id}</option>`).join('')}</select>`;}

function chart(){return '';}

function logsPage(){return unavailablePage('Log viewer & correlation','Import well evidence first. Scientific log parsing and rendering are not available yet.');}

function qcPage(){return unavailablePage('QA/QC & repairs','Original files are retained. Scientific curve conditioning is not available yet.');}

function field(label,value,index=fieldIndex++){let opts=value.includes('|');return `<label class="field">${esc(label)}${opts?`<select name="f${index}">${value.split('|').map(v=>`<option>${esc(v)}</option>`).join('')}</select>`:`<input name="f${index}" value="${esc(value)}" placeholder="${value?'':'Required for calculation'}">`}</label>`;}

function modulePage(m){let vals=state.configs[m.id]?.values;return heading(m.name,m.description,btn('Save configuration','save-module',true))+(['Qualitative','Quantitative'].includes(m.group)?stepper(m.group==='Qualitative'?'qualitative':'quantitative'):'')+`<div class="tabs">${['Workbench','Parameters','Inputs & evidence','Results','Features'].map(t=>`<button class="${formTab===t?'active':''}" data-formtab="${t}">${t}</button>`).join('')}</div>`+(formTab==='Workbench'?specialist(m,state):formTab==='Features'?panel('Included feature groups',`<div class="panel-body">${m.features.map(t=>`<div class="status-row"><span>${t}</span><button data-feature="${esc(t)}">Configure</button></div>`).join('')}<p class="sub" style="margin-top:15px">This inventory tracks frontend coverage, not computational availability.</p></div>`):formTab==='Inputs & evidence'?panel('Input contract',`<div class="panel-body"><div class="note amber">No calculation service or authoritative datasets are connected. Source selection here is a frontend configuration.</div><form id="module-inputs" style="margin-top:20px"><div class="form-grid">${field('Well',wells.map(w=>w.id).join('|'))}${field('Evidence source','Not connected|Reviewed curve version|Core dataset|External reference')}${field('Depth reference','MD|TVD|TVDSS')}${field('Source version ID','')}</div><button type="submit">Save input selection</button></form></div>`):formTab==='Results'?panel('Results',`<div class="empty">${icon('logs')}<strong>Awaiting a connected calculation service</strong><p>Saved settings are ready for integration. No ${m.name.toLowerCase()} results have been calculated.</p>${btn('View saved configuration','view-config')}</div>`):`<div class="grid"><section class="panel"><header class="panel-head"><h2>Evaluation settings</h2>${badge(state.configs[m.id]?'Draft saved':'Not configured','gray')}</header><div class="panel-body"><form id="module-form"><div class="form-grid">${(m.fields||[['Scenario name','Base case'],['Input dataset','Not connected']]).map(([k,v],i)=>field(k,vals?.[i]&&v.includes('|')?[vals[i],...v.split('|').filter(x=>x!==vals[i])].join('|'):vals?.[i]??v,i)).join('')}</div><label class="field">Interpretation notes<textarea name="notes" placeholder="Record assumptions and supporting references…">${esc(state.configs[m.id]?.notes||'')}</textarea></label><div class="actions"><button class="primary" type="submit">Save configuration</button>${btn('Duplicate scenario','duplicate')}</div></form></div></section><div>${panel('Evidence requirements',`<div class="panel-body"><div class="note amber">Calculation unavailable until input versions, units, method applicability and required calibration evidence are validated by the backend.</div>${m.features.slice(0,4).map(t=>`<div class="status-row"><span>${t}</span>${badge('Review needed','gray')}</div>`).join('')}</div>`)}${panel('Provenance',`<div class="panel-body"><div class="status-row"><span>Role</span><strong>Draft configuration</strong></div><div class="status-row"><span>Original sources</span><span>Preserved</span></div><div class="status-row"><span>Calculation</span><span>Not run</span></div>${go('reviews','Open version history')}</div>`)}</div></div>`);}

function cutoffsPage(){return unavailablePage('Cutoff determination','Reviewed property curves are required. No reservoir or pay calculations have been run.');}

function summaries(){return unavailablePage('Reservoir summaries','No evaluated reservoir results are available. Import sources and configure your interpretation first.');}

function reports(){return heading('Reports & exports','Export the complete project and its original evidence.',btn('Download project','export-workspace',true))+panel('Project evidence',`<div class="panel-body"><h3>${esc(state.project)}</h3><p>${state.files.length} stored source files · ${Object.keys(state.configs).length} saved configurations.</p><p class="sub">Scientific report generation is not available yet.</p></div>`);}

function reviews(){return heading('Reviews & history','Follow local decisions and inspect saved configuration versions.',btn('Export workspace','export-workspace'))+`<div class="grid">${panel('Activity timeline',`<div class="panel-body">${activityList(30)}</div>`)}${panel('Saved configurations',`<div class="panel-body">${Object.keys(state.configs).length?Object.entries(state.configs).map(([id,c])=>`<div class="version"><div>${icon('file')}</div><div><strong>${esc(modules.find(m=>m.id===id)?.name||id)}</strong><p>Version ${c.version} · Draft only</p>${go(id,'Open configuration')}</div></div>`).join(''):'<div class="empty"><strong>No configurations saved yet</strong>Open an interpretation tool to define a draft.</div>'}</div>`)}</div>`;}

function settings(){let pref=state.preferences||{},val=(k,d)=>pref[k]??d;let select=(k,t,opts,d)=>`<label class="field">${t}<select name="${k}">${opts.map(v=>`<option ${val(k,d)===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;let input=(k,t,d)=>`<label class="field">${t}<input name="${k}" value="${esc(val(k,d))}"></label>`;let toggle=(k,t,d=true)=>`<label class="setting-toggle"><span>${t}</span><input name="${k}" type="checkbox" ${val(k,d)?'checked':''}></label>`;return heading('Settings','Set up your project and make the workspace feel like yours.',btn('Save preferences','save-settings',true))+`<form id="settings-form"><div class="settings-layout"><nav class="settings-index" aria-label="Settings sections">${['Profile','Project','Appearance','Units & references','Log viewer','Map defaults','Workflow & reviews','Notifications','Exports','Data & access'].map((t,i)=>`<a href="#" data-settingsection="settings-${i}">${t}</a>`).join('')}</nav><div><section class="panel" id="settings-0"><header class="panel-head"><h2>Profile & identity</h2></header><div class="panel-body"><div class="profile-preview"><div class="avatar">${esc(profileInitials())}</div><div><strong>${esc(profileName())}</strong><small>StrataX account profile</small></div></div><div class="form-grid">${input('displayName','Display name','TerraCode Analytics')}${input('jobTitle','Role / title','Petrophysicist')}${input('organization','Organization','TerraCode Analytics Limited')}${select('timezone','Display timezone',['Africa/Lagos','UTC','Europe/London'],'Africa/Lagos')}</div></div></section><section class="panel" id="settings-1"><header class="panel-head"><h2>Project details</h2></header><div class="panel-body"><div class="form-grid">${field('Project name',state.project,0)}${input('projectCode','Project code','')}${input('basin','Basin / region',projectContext()?.location||'')}${select('formationProfile','Formation profile',['Young clastic','Old clastic','Carbonate','Mixed / custom'],'Young clastic')}</div><label class="field">Project notes<textarea name="notes">${esc(state.projectNotes||'')}</textarea></label></div></section><section class="panel" id="settings-2"><header class="panel-head"><h2>Appearance & accessibility</h2></header><div class="panel-body"><div class="form-grid">${select('density','Interface density',['Comfortable','Compact'],'Comfortable')}${select('fontSize','Text size',['Standard','Large'],'Standard')}${select('accent','Accent color',['Teal','Forest'],'Teal')}${select('startPage','Workspace start page',['Projects','Overview'],'Projects')}</div>${toggle('reducedMotion','Reduce animations',false)}<p class="note">Density, text size, accent and motion preferences apply to this browser.</p></div></section><section class="panel" id="settings-3"><header class="panel-head"><h2>Units & coordinate references</h2></header><div class="panel-body form-grid">${select('depthUnit','Depth unit',['Feet','Metres'],'Feet')}${select('depthReference','Depth reference',['MD','TVD','TVDSS'],'MD')}${select('porosityUnit','Porosity display',['Fraction','Percent'],'Fraction')}${select('pressureUnit','Pressure',['psi','bar','MPa'],'psi')}${input('horizontalCRS','Horizontal CRS / EPSG','Unconfirmed')}${input('verticalDatum','Vertical datum','Unconfirmed')}</div><div class="panel-body"><p class="note">Unit and CRS defaults are configuration preferences. They do not convert existing evidence or confirm source references.</p></div></section><section class="panel" id="settings-4"><header class="panel-head"><h2>Log viewer defaults</h2></header><div class="panel-body"><div class="form-grid">${select('viewerTemplate','Default template',['Triple combo','Petrophysics','Correlation','Custom'],'Triple combo')}${select('depthDirection','Depth direction',['Increasing downward','Increasing upward'],'Increasing downward')}${select('trackWidth','Track width',['Standard','Wide','Narrow'],'Standard')}${select('curveThickness','Curve line weight',['Fine','Standard','Bold'],'Standard')}</div>${toggle('linkedDepth','Link depth across wells')}${toggle('gridDefault','Show log grid by default')}</div></section><section class="panel" id="settings-5"><header class="panel-head"><h2>Map defaults</h2></header><div class="panel-body form-grid">${select('mapDefault','Preferred basemap',['Terrain','Street','Satellite','Blank'],'Terrain')}${select('mapUnits','Measurement units',['Metric','Imperial'],'Metric')}${select('wellLabels','Well label visibility',['Always','Selected only','Hidden'],'Always')}${select('coordinateFormat','Coordinate format',['Decimal degrees','Degrees minutes seconds','Projected coordinates'],'Decimal degrees')}</div></section><section class="panel" id="settings-6"><header class="panel-head"><h2>Workflow & review</h2></header><div class="panel-body"><div class="form-grid">${select('approvalPolicy','Review policy',['Explicit reviewer acceptance','Draft comparison only'],'Explicit reviewer acceptance')}${select('nullPolicy','Missing-data policy',['Preserve and flag','Exclude with reason'],'Preserve and flag')}${select('versionLabel','Version naming',['Automatic sequence','Date and sequence'],'Automatic sequence')}${select('stalePolicy','Changed-input behavior',['Flag downstream results','Require re-review'],'Flag downstream results')}</div><p class="note">These configure the intended workflow. Scientific approvals and policy enforcement require the backend.</p></div></section><section class="panel" id="settings-7"><header class="panel-head"><h2>Notifications</h2></header><div class="panel-body">${toggle('notifications','Show in-app notifications')}${toggle('reviewAlerts','Highlight pending reviews')}<div class="form-grid" style="margin-top:18px">${select('digest','Future email digest',['Off','Daily','Weekly'],'Off')}${select('notificationScope','Notification scope',['My projects','Assigned to me'],'My projects')}</div><p class="note">Project notification emails are not available.</p></div></section><section class="panel" id="settings-8"><header class="panel-head"><h2>Reports & exports</h2></header><div class="panel-body form-grid">${select('paperSize','Paper size',['A4','Letter','A3'],'A4')}${select('reportOrientation','Report orientation',['Portrait','Landscape'],'Portrait')}${select('decimalPlaces','Decimal precision',['2','3','4','6'],'3')}${select('dataExport','Default data format',['CSV','JSON','LAS'],'CSV')}${input('reportAuthor','Report author',profileName())}${select('reportAppendix','Provenance appendix',['Include','Exclude from draft'],'Include')}</div></section><section class="panel" id="settings-9"><header class="panel-head"><h2>Data portability & access</h2></header><div class="panel-body"><p class="sub">Project work uses the destination selected during setup. Cloud records are owner-only; sharing and invitations are not available.</p><div class="actions" style="margin-top:18px">${btn('Export workspace','export-workspace')}</div></div></section><div class="settings-save"><button type="submit" class="primary">Save all preferences</button><span>Check the save indicator for project changes</span></div></div></div></form>`;}

function catalog(){return heading('Complete feature inventory',`${modules.length} workspaces covering the agreed product scope. Coverage describes interface status, not scientific implementation.`,btn(icon('download')+'Export inventory','export-catalog'))+`<div class="panel"><div class="toolbar"><input id="catalog-search" aria-label="Filter feature inventory" placeholder="Find a workspace or microfeature…" value="${esc(search)}"><span class="badge gray">${modules.reduce((a,m)=>a+m.features.length,0)} feature groups</span></div><div class="table-wrap"><table class="catalog-table"><thead><tr><th>Area</th><th>Workspace</th><th>Microfeatures specified</th><th>Interface coverage</th><th></th></tr></thead><tbody>${modules.filter(m=>allowedTool(m.id,projectContext(),modules)&&(m.name+' '+m.group+' '+m.features.join(' ')).toLowerCase().includes(search.toLowerCase())).map(m=>`<tr><td>${m.group}</td><td class="well-name">${m.name}</td><td>${m.features.map(esc).join(' · ')}</td><td>${badge(['files','wells','documents','map','logs','qc','cutoffs','summaries','reports','reviews','settings'].includes(m.id)?'Interactive workspace':'Configuration + requirements','gray')}</td><td>${go(m.id,'Open '+icon('arrow'))}</td></tr>`).join('')}</tbody></table></div></div>`;}

function modal(title,body,footer=''){let d=$('#dialog');d.oncancel=null;d.classList.remove('setup-dialog','ingestion-dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="quiet icon" data-close aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;d.showModal();d.querySelector('[data-close]').onclick=()=>d.close();d.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{d.close();navigate(b.dataset.go);});}

function download(name,data,type='application/json'){let blob=new Blob([data],{type});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}

function saveModule(){let m=modules.find(x=>x.id===route),form=$('#module-form');if(!m)return;if(!form){formTab='Parameters';render();toast('Edit parameters, then save the configuration.');return;}let data=new FormData(form);state.configHistory=state.configHistory||{};state.configHistory[m.id]=state.configHistory[m.id]||[];if(state.configs[m.id])state.configHistory[m.id].push(structuredClone(state.configs[m.id]));state.configs[m.id]={values:(m.fields||[1,2]).map((_,i)=>String(data.get('f'+i)||'')),notes:data.get('notes'),version:(state.configs[m.id]?.version||0)+1,updatedAt:new Date().toISOString()};log(`Saved ${m.name} configuration`);toast('Configuration queued for saving. No calculation has been run.');render();}

function bind(){bindWorkbench();bindPublic();document.querySelectorAll('[data-settingsection]').forEach(a=>a.onclick=e=>{e.preventDefault();$('#'+a.dataset.settingsection)?.scrollIntoView({behavior:'smooth',block:'start'});});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-well]').forEach(b=>b.onclick=()=>{state.well=b.dataset.well;save();navigate('logs');});document.querySelectorAll('[data-mapwell]').forEach(b=>{b.onclick=e=>{e.stopPropagation();state.mapSelected=b.dataset.mapwell;state.well=b.dataset.mapwell;save();if(route==='map')render();else navigate('map');};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')b.click();};});document.querySelectorAll('[data-layer]').forEach(b=>b.onchange=()=>{state.layers[b.dataset.layer]=b.checked;save();render();});document.querySelectorAll('[data-datatab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.datatab;state.filters='All';save();navigate(b.dataset.datatab);});document.querySelectorAll('[data-formtab]').forEach(b=>b.onclick=()=>{formTab=b.dataset.formtab;render();});document.querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>featureEditor(b.dataset.feature));document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>fileReview(b.dataset.file));if($('#well-select'))$('#well-select').onchange=e=>{state.well=e.target.value;save();render();};if($('#basemap'))$('#basemap').onchange=e=>{state.basemap=e.target.value;save();render();};if($('#opacity'))$('#opacity').onchange=e=>{state.opacity=+e.target.value;save();render();};if($('#map-surface'))$('#map-surface').onclick=e=>{if(!state.measurement||e.target.closest('button')||e.target.closest('[data-mapwell]'))return;let r=$('#map-surface').getBoundingClientRect();state.measurePoints.push({x:(e.clientX-r.left)/r.width*900,y:(e.clientY-r.top)/r.height*550});save();render();};for(let id of ['filter-data','catalog-search'])if($('#'+id))$('#'+id).oninput=e=>{let pos=e.target.selectionStart;search=e.target.value;render();let el=$('#'+id);el.focus();el.setSelectionRange(pos,pos);};if($('#doc-family'))$('#doc-family').onchange=e=>{state.filters=e.target.value;save();render();};if($('#recipe-select'))$('#recipe-select').onchange=e=>{state.qcRecipe=e.target.value;state.qcPreview=false;state.qcDecision=null;save();render();};if($('#qc-form'))$('#qc-form').onsubmit=e=>{e.preventDefault();state.qcPreview=true;log('Opened demonstration '+state.qcRecipe.toLowerCase()+' preview');render();};if($('#module-form'))$('#module-form').onsubmit=e=>{e.preventDefault();saveModule();};if($('#module-inputs'))$('#module-inputs').onsubmit=e=>{e.preventDefault();state.moduleInputs=state.moduleInputs||{};state.moduleInputs[route]=Object.fromEntries(new FormData(e.target));log('Saved local input selection for '+route);toast('Input selection recorded locally. Scientific input validation is not connected.');};for(let k of ['vsh','phi','sw'])if($('#cut-'+k))$('#cut-'+k).oninput=e=>{state.cutoffs[k]=+e.target.value;save();render();$('#cut-'+k).focus();};if($('#settings-form'))$('#settings-form').onsubmit=async e=>{e.preventDefault();let f=e.target;try{session.account=await api('/api/account',{method:'PUT',body:{display_name:f.elements.namedItem('displayName').value,organization:f.elements.namedItem('organization').value}});}catch(error){toast(error.message);return;}state.settingsDraft=Object.fromEntries(new FormData(f));state.preferences={...state.preferences,...Object.fromEntries(new FormData(f))};for(let key of ['notifications','reviewAlerts','linkedDepth','autosave','gridDefault','reducedMotion'])state.preferences[key]=f.elements.namedItem(key)?.checked||false;state.project=f.elements.f0.value;let p=projectContext();if(p){p.name=state.project;p.updatedAt=new Date().toISOString();}state.projectNotes=f.elements.notes.value;if(state.preferences.mapDefault)state.basemap=state.preferences.mapDefault;log('Updated local project settings');toast('Project settings saved.');render();};if($('#depth-view'))$('#depth-view').onchange=e=>{if(e.target.value!=='MD / ft')toast('Depth conversion awaits a reviewed survey and datum. Chart remains MD.');};}

function action(a){
 if(['project-settings','save-project','export-workspace','open-local','import-package'].includes(a)){projectAction(a);return;}
 if(a==='signout'){logout().catch(error=>toast(error.message));return;}
 if(a==='help'){openHelp();return;}if(a==='projects'){navigate('projects');return;}
 if(a==='menu'){$('.sidebar').classList.toggle('open');return;}
 if(a==='search'){searchModal();return;}if(a==='upload'){uploadModal();return;}
 if(a==='save-module'){saveModule();return;}if(a==='save-settings'){$('#settings-form').requestSubmit();return;}
 if(a==='export-catalog'){download('StrataX_feature_inventory.json',JSON.stringify(modules.filter(m=>allowedTool(m.id,projectContext(),modules)),null,2));return;}
 if(a==='export-files'){download('StrataX_source_inventory.json',JSON.stringify(state.files,null,2));return;}
 if(a==='print'){window.print();return;}
 if(a==='notifications'){modal('Project notifications','<p>No pending review notifications.</p>');return;}
 if(a==='add-well'){modal('Register a well',`<form id="well-form"><label class="field">Well ID<input name="id" required maxlength="100"></label><label class="field">Source reference<input name="source" maxlength="200"></label><button class="primary">Save registration</button></form>`);$('#well-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),id=String(f.get('id')).trim();if(!id||wells.some(w=>w.id===id)){toast('Enter a unique well ID.');return;}state.wellDrafts||=[];state.wellDrafts.push({id,source:f.get('source'),depth:'Not parsed',curves:0,status:'Unvalidated registration'});wells=state.wellDrafts;log('Registered well '+id);$('#dialog').close();render();};return;}
 if(a==='duplicate'){toast('Export a project package to create an independent copy.');return;}
 if(a==='view-config'){formTab='Parameters';render();return;}
 toast('This capability is not available yet. Your saved evidence is retained.');
}

function searchModal(){modal('Search workspace',`<input id="global-search" placeholder="Try saturation, TMB-04, maps…" aria-label="Search workspace" style="width:100%"><div id="search-results" style="margin-top:15px;max-height:380px;overflow:auto"></div>`);let populate=q=>{$('#search-results').innerHTML=[...modules.filter(m=>allowedTool(m.id,projectContext(),modules)&&(m.name+' '+m.features.join(' ')).toLowerCase().includes(q.toLowerCase())).map(m=>({label:m.name,sub:m.group,id:m.id})),...wells.filter(w=>w.id.toLowerCase().includes(q.toLowerCase())).map(w=>({label:w.id,sub:'Well · Open log viewer',id:'logs',well:w.id}))].slice(0,12).map(r=>`<button class="search-result" data-result="${r.id}" ${r.well?`data-resultwell="${r.well}"`:''}>${esc(r.label)}<small>${esc(r.sub)}</small></button>`).join('')||'<p class="sub">No matching workspace items.</p>';document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{if(b.dataset.resultwell)state.well=b.dataset.resultwell;$('#dialog').close();navigate(b.dataset.result);});};populate('');$('#global-search').oninput=e=>populate(e.target.value);$('#global-search').focus();}

function uploadModal(){openImporter().catch(error=>toast(error.message));}

function fileReview(name){const file=state.files.find(f=>f.name===name);if(!file)return;modal('Source file',`<h3>${esc(file.name)}</h3><p>${esc(file.status)}</p><p class="sub">Original retained. Scientific parsing is not available yet.</p><button id="download-original" class="primary">Download original</button>`);$('#download-original').onclick=async()=>{try{blobDownload(file.name,await repository.source(projectContext(),file));}catch(error){toast(error.message);}};}

document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();if(!$('#dialog').open)searchModal();}});window.addEventListener('hashchange',()=>{let next=location.hash.slice(1)||'home';if(next!==route){route=next;render();}});

function featureEditor(feature){let key=route+':'+feature;let spec=state.featureSpecs?.[key]||{};modal(feature,`<p class="sub">${esc(modules.find(m=>m.id===route)?.name)} / Feature specification</p><form id="feature-form" style="margin-top:20px"><div class="form-grid"><label class="field">Scope<select name="scope"><option>Selected well and interval</option><option>Selected wells</option><option>Project</option></select></label><label class="field">Review requirement<select name="review"><option>Reviewer acceptance required</option><option>Draft / comparison only</option></select></label><label class="field">Input version / source<input name="input" value="${esc(spec.input||'')}" placeholder="Awaiting connected evidence"></label><label class="field">Parameter expression / configuration<input name="parameters" value="${esc(spec.parameters||'')}" placeholder="Define values and units"></label></div><label class="field">Requirements and acceptance notes<textarea name="notes">${esc(spec.notes||'')}</textarea></label><div class="note">Saving records the interface specification. It does not execute the feature or establish evidence eligibility.</div><button class="primary" style="margin-top:16px">Save feature specification</button></form>`);$('#feature-form').onsubmit=e=>{e.preventDefault();state.featureSpecs=state.featureSpecs||{};state.featureSpecs[key]=Object.fromEntries(new FormData(e.target));log('Configured '+feature);$('#dialog').close();toast('Feature specification queued for saving.');};}

function bindWorkbench(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.workbenchUI=state.workbenchUI||{};state.workbenchUI[route]={...state.workbenchUI[route],view:b.dataset.view};save();render();});let ws=$('#workbench-well');if(ws)ws.onchange=e=>{state.well=e.target.value;save();render();};for(let [id,k] of [['show-overlay','overlay'],['link-depth','linkDepth']])if($('#'+id))$('#'+id).onchange=e=>{state.workbenchUI=state.workbenchUI||{};state.workbenchUI[route]={...state.workbenchUI[route],[k]:e.target.checked};save();if(k==='overlay')$('.visual-canvas')?.classList.toggle('overlay-off',!e.target.checked);};document.querySelectorAll('[data-sample]').forEach(b=>{b.onclick=()=>modal('Synthetic sample '+b.dataset.sample,`<div class="note">Illustrative point for interaction review. There is no field measurement associated with this point.</div><div class="status-row"><span>Sample reference</span><strong>EX-${b.dataset.sample}</strong></div><div class="status-row"><span>Well context</span><strong>${state.well}</strong></div>`);b.onkeydown=e=>{if(e.key==='Enter')b.click();};});}

function annotationEditor(){modal('Add review annotation',`<form id="annotation-form"><label class="field">Annotation<textarea name="text" required placeholder="Record your observation…"></textarea></label><label class="field">Depth, sample or view reference<input name="reference" placeholder="For example: EX-25, Zone A"></label><button class="primary">Save annotation</button></form>`);$('#annotation-form').onsubmit=e=>{e.preventDefault();state.annotations=state.annotations||{};state.annotations[route]=state.annotations[route]||[];state.annotations[route].push(Object.fromEntries(new FormData(e.target)));log('Added '+route+' review annotation');$('#dialog').close();render();};}

function renderProjects(){let records=portfolio.records.filter(p=>projectFilter==='Trash'?p.status==='Trash':projectFilter==='Archived'?p.status==='Archived':projectFilter==='Favorites'?p.favorite&&p.status!=='Trash':projectFilter==='All'?p.status!=='Trash':p.status==='Active').filter(p=>(p.name+' '+p.description+' '+p.location).toLowerCase().includes(projectQuery.toLowerCase()));records.sort((a,b)=>projectSort==='name'?a.name.localeCompare(b.name):projectSort==='created'?b.createdAt.localeCompare(a.createdAt):b.updatedAt.localeCompare(a.updatedAt));let active=portfolio.records.filter(p=>p.status==='Active').length;$('#app').innerHTML=directoryView({records,portfolio,projectFilter,projectQuery,projectView,projectSort,projectCard,projectActions,projectInsights,profileMenu,icon,esc});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(b.dataset.action==='new-project')projectEditor();else action(b.dataset.action);});document.querySelectorAll('[data-progress]').forEach(b=>b.onclick=()=>progressEditor(b.dataset.progress));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-projectfilter]').forEach(b=>b.onclick=()=>{projectFilter=b.dataset.projectfilter;renderProjects();});document.querySelectorAll('[data-projectview]').forEach(b=>b.onclick=()=>{projectView=b.dataset.projectview;renderProjects();});document.querySelectorAll('[data-openproject]').forEach(b=>b.onclick=()=>openProject(b.dataset.openproject));document.querySelectorAll('[data-projectmenu]').forEach(b=>b.onclick=()=>projectMenu(b.dataset.projectmenu));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{let p=portfolio.records.find(p=>p.id===b.dataset.favorite);p.favorite=!p.favorite;persistPortfolio();renderProjects();});$('#project-search').oninput=e=>{projectQuery=e.target.value;let pos=e.target.selectionStart;renderProjects();$('#project-search').focus();$('#project-search').setSelectionRange(pos,pos);};$('#project-sort').onchange=e=>{projectSort=e.target.value;renderProjects();};bindPublic();$('#clear-project-search')?.addEventListener('click',()=>{projectQuery='';renderProjects();$('#project-search').focus();});}

function projectActions(p){return `<div class="actions">${p.status!=='Trash'?`<button data-openproject="${p.id}">Open project ${icon('arrow')}</button>`:''}<button data-projectmenu="${p.id}" aria-label="Manage ${esc(p.name)}">${icon('settings')}</button></div>`;}

function projectCard(p){return cardView(p,{portfolio,progressFor,stages:projectStages(p),icon,esc,badge});}

function projectEditor(id){const current=portfolio.records.find(p=>p.id===id);projectSetup({project:current,modal,complete:async draft=>{if(portfolio.records.some(p=>p.id!==draft.id&&p.status!=='Trash'&&p.name.toLowerCase()===draft.name.toLowerCase()))throw new Error('A project with this name already exists.');const now=new Date().toISOString();draft.createdAt=draft.createdAt||now;draft.updatedAt=now;draft.favorite=!!draft.favorite;const context=current?structuredClone(current.id===portfolio.activeId?state:portfolio.contexts[current.id]||freshProjectContext(draft.name)):freshProjectContext(draft.name);context.project=draft.name;if(!current)context.audit.unshift({action:'Created project',time:now});await flushProjectSaves();if(current)draft.revision=current.revision||0;const result=await repository.save(draft,context);draft.revision=result.revision||0;if(current)Object.assign(current,draft);else portfolio.records.push(draft);portfolio.contexts[draft.id]=result.workspace||context;portfolio.activeId=draft.id;state=structuredClone(portfolio.contexts[draft.id]);saveStates.set(draft.id,result.unsaved?'Unsaved changes':'Saved');rememberSnapshot(draft);localStorage.setItem(storageKey('stratax.projects.v2'),JSON.stringify(portfolio));navigate('overview');}});}

function freshProjectContext(name){return {...structuredClone(initial),project:name};}

async function openProject(id){const p=portfolio.records.find(p=>p.id===id);if(!p||p.status==='Trash')return;try{await flushProjectSaves();const record=p.storage==='legacy'?{workspace:portfolio.contexts[id]||freshProjectContext(p.name)}:await repository.load(p);portfolio.activeId=id;state={...structuredClone(initial),...record.workspace,project:p.name};if(record.project)Object.assign(p,record.project,{revision:record.revision});portfolio.contexts[id]=structuredClone(state);wells=state.wellDrafts||[];p.lastOpenedAt=new Date().toISOString();rememberSnapshot(p);localStorage.setItem(storageKey('stratax.projects.v2'),JSON.stringify(portfolio));navigate('overview');}catch(error){toast(error.message);}}

function projectMenu(id){let p=portfolio.records.find(p=>p.id===id);if(!p)return;modal('Manage '+esc(p.name),`<div class="project-menu"><button id="project-edit">${icon('file')}Edit project details</button><button id="project-duplicate">${icon('layers')}Duplicate project</button><button id="project-archive">${icon('clock')}${p.status==='Archived'?'Restore to active projects':'Archive project'}</button>${p.status==='Trash'?'<button id="project-restore">Restore from trash</button>':'<button id="project-trash" class="danger">Move to trash</button>'}</div><p class="note" style="margin-top:18px">Archived projects remain available. Projects in Trash can be restored. Project data is retained in its selected storage destination.</p>`);$('#project-edit').onclick=()=>{$('#dialog').close();projectEditor(id);};$('#project-duplicate').onclick=async()=>{try{await flushProjectSaves();const context=id===portfolio.activeId?state:(await repository.load(p)).workspace;const blob=await repository.exportPackage(p,context);const copy=await repository.importPackage(blob);copy.project.name=p.name+' copy';copy.project.status='Active';copy.project.favorite=false;$('#dialog').close();await attachLocal(copy);toast('Independent portable copy created. Download it to retain the copy.');}catch(error){toast(error.message);}};$('#project-archive').onclick=()=>{p.status=p.status==='Archived'?'Active':'Archived';p.updatedAt=new Date().toISOString();persistPortfolio();$('#dialog').close();renderProjects();toast(p.status==='Archived'?'Project archived.':'Project restored.');};if($('#project-trash'))$('#project-trash').onclick=()=>{modal('Move project to trash?',`<p><strong>${esc(p.name)}</strong> will be removed from your project lists. Its local workspace can be restored from Trash.</p><div class="actions" style="margin-top:20px"><button id="confirm-project-trash" class="danger">Move to trash</button><button id="cancel-project-trash">Cancel</button></div>`);$('#cancel-project-trash').onclick=()=>$('#dialog').close();$('#confirm-project-trash').onclick=()=>{p.previousStatus=p.status;p.status='Trash';p.updatedAt=new Date().toISOString();persistPortfolio();$('#dialog').close();renderProjects();toast('Project moved to Trash. You can restore it.');};};if($('#project-restore'))$('#project-restore').onclick=()=>{p.status=p.previousStatus||'Active';p.updatedAt=new Date().toISOString();persistPortfolio();$('#dialog').close();renderProjects();toast('Project restored.');};}

function publicHeader(){return publicHeaderView(icon);}

function renderPublicPage(){if(route==='home')renderLanding();else renderAccount(route);}

function renderLanding(){renderLandingView(icon,chart);}

function newProjectOverview(){return overview();}

function localProjectId(){return typeof crypto.randomUUID==='function'?crypto.randomUUID():'project-'+Date.now().toString(36)+'-'+Array.from(crypto.getRandomValues(new Uint8Array(8)),v=>v.toString(16).padStart(2,'0')).join('');}

function profileName(){return state.preferences?.displayName||session.account?.display_name||session.user?.displayName||session.user?.email?.split('@')[0]||'StrataX account';}

function profileInitials(){return profileName().trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();}

function profileMenu(){return accountMenu(icon);}

function toggleProfile(){let p=$('#profile-popover'),t=$('[data-action=profile]');if(!p)return;p.hidden=!p.hidden;t.setAttribute('aria-expanded',String(!p.hidden));}

document.addEventListener('click',e=>{if(!e.target.closest('.profile-anchor')){let p=$('#profile-popover');if(p){p.hidden=true;$('[data-action=profile]')?.setAttribute('aria-expanded','false');}}});

function applyPreferences(){let p=state.preferences||{};document.documentElement.dataset.density=p.density||'Comfortable';document.documentElement.dataset.textsize=p.fontSize||'Standard';document.documentElement.dataset.accent=p.accent||'Teal';document.documentElement.dataset.curveweight=p.curveThickness||'Standard';document.documentElement.dataset.loggrid=p.gridDefault===false?'hidden':'visible';document.documentElement.dataset.motion=p.reducedMotion?'reduced':'normal';}

function progressFor(p){const list=projectStages(p),context=portfolio.contexts[p.id]||{},states=list.map(([k])=>p.stageStates?.[k]||(k==='collection'&&context.files?.length?'In progress':'Not started'));return {completed:states.filter(s=>s==='Completed').length,inprogress:states.filter(s=>s==='In progress').length,notstarted:states.filter(s=>s==='Not started').length,total:list.length};}

function donut(x,size='large'){let total=x.total||1,a=x.completed/total*100,b=x.inprogress/total*100;return `<div class="donut ${size}" role="img" aria-label="${x.completed} completed, ${x.inprogress} in progress, ${x.notstarted} not started" style="background:conic-gradient(#138a74 0 ${a}%,#d2a454 ${a}% ${a+b}%,#e5ece6 ${a+b}% 100%)"><div><strong>${Math.round(a)}<small>%</small></strong><span>completed</span></div></div>`;}

function projectInsights(){return insightsView({portfolio,progressFor,icon,esc});}

function projectCardProgress(p){let x=progressFor(p);return `<div class="card-progress">${donut(x,'small')}<div><strong>${x.completed} of ${x.total} stages complete</strong><div class="card-progress-legend"><span><i class="inprogress"></i>${x.inprogress} in progress</span><span><i class="notstarted"></i>${x.notstarted} not started</span></div><button class="quiet progress-edit" data-progress="${p.id}">Update progress</button></div></div>`;}

function progressEditor(id){let p=portfolio.records.find(p=>p.id===id),x=progressFor(p);if(!p)return;modal('Update workflow progress',`<p class="sub">${esc(p.name)} · User-reported workflow tracking</p><form id="progress-form" style="margin-top:20px">${projectStages(p).map(([k,t],i)=>`<label class="field">${i+1}. ${t}<select name="${k}">${['Not started','In progress','Completed'].map(v=>`<option ${(p.stageStates?.[k]||(i<x.completed?'Completed':i<x.completed+x.inprogress?'In progress':'Not started'))===v?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<p class="note">This records project tracking status only. It does not approve a scientific result.</p><button class="primary" style="margin-top:18px">Save progress</button></form>`);$('#progress-form').onsubmit=e=>{e.preventDefault();p.stageStates=Object.fromEntries(new FormData(e.target));p.progress={completed:0,inprogress:0,notstarted:0};for(let v of Object.values(p.stageStates))p.progress[v==='Completed'?'completed':v==='In progress'?'inprogress':'notstarted']++;p.updatedAt=new Date().toISOString();persistPortfolio();$('#dialog').close();renderProjects();toast('Project progress updated.');};}

const helpTopics=[['Project setup','Choose Petrophysics, Seismic interpretation, or both. Add a site location and choose Cloud or Local storage. You can change workflows in Project settings without losing saved work.'],['Saving','Cloud projects follow your account. Local folder projects save on this device. Portable projects require Download project to keep changes. Check the save indicator before leaving.'],['Source files','Original files are retained in your chosen destination. Parsing, OCR and scientific calculations are not available yet.'],['Maps','Add WGS84 site coordinates in Project settings. Online basemaps and place search contact Google.'],['Recovery drafts','Existing browser projects remain recoverable. Choose a storage destination before continuing work.']];

function openHelp(){modal('Help & keyboard shortcuts',`<div class="help-intro"><span class="help-symbol">${icon('help')}</span><div><h3>A little guidance, right where you work.</h3><p class="sub">Find a workflow topic or learn a faster way around.</p></div></div><input id="help-search" aria-label="Search help" placeholder="Search help topics…" style="width:100%;margin:18px 0"><div class="help-shortcuts"><h3>Keyboard shortcuts</h3>${[['Ctrl / ⌘ K','Search workspace'],['Alt P','All projects'],['Alt O','Project overview'],['Alt M','Map workspace'],['Alt L','Log viewer'],['Alt S','Settings'],['Shift ?','Open help'],['Escape','Close dialog or profile menu']].map(([k,t])=>`<div><span>${t}</span><kbd>${k}</kbd></div>`).join('')}</div><div id="help-topics">${helpTopics.map(([t,d])=>`<details class="help-topic"><summary>${t}</summary><p>${d}</p></details>`).join('')}</div><div class="note" style="margin-top:18px">Shortcuts are inactive while typing in form fields.</div>`);$('#help-search').oninput=e=>{let q=e.target.value.toLowerCase();document.querySelectorAll('.help-topic').forEach(d=>d.hidden=!d.textContent.toLowerCase().includes(q));};}

document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#profile-popover')?.setAttribute('hidden','');$('[data-action=profile]')?.setAttribute('aria-expanded','false');return;}if(e.target.closest('input,textarea,select,[contenteditable=true]'))return;if(e.key==='?'&&!$('#dialog').open){e.preventDefault();openHelp();return;}if(e.altKey&&!$('#dialog').open){let r={p:'projects',o:'overview',m:'map',l:'logs',s:'settings'}[e.key.toLowerCase()];if(r){e.preventDefault();navigate(r);}}});

let loadedUid=null;

async function restoreUserWorkspace(){const uid=session.user?.uid||null;if(uid!==loadedUid){loadedUid=uid;clearTimeout(saveTimer);repository.resetRepository();saveSnapshots.clear();saveStates.clear();saveConflicts.clear();state=structuredClone(initial);portfolio={records:[],activeId:null,contexts:{}};if(uid){try{const saved=JSON.parse(localGet(storageKey('stratax.projects.v2'))||'null');if(saved?.records){portfolio=saved;portfolio.contexts||={};if(!localGet(storageKey('stratax.projects.recovery.v2')))localStorage.setItem(storageKey('stratax.projects.recovery.v2'),JSON.stringify(saved));portfolio.records=portfolio.records.filter(p=>{if(!p.demo)return true;const c=portfolio.contexts[p.id]||{};const realFiles=(c.files||[]).filter(f=>f.local);if(realFiles.length||Object.keys(c.configs||{}).length){p.demo=false;p.name+=' recovery';p.storage='legacy';c.files=realFiles;c.well='';c.audit=(c.audit||[]).filter(a=>!/(demonstration|example|synthetic)/i.test(a.action));return true;}return false;});for(const p of portfolio.records){p.storage=p.storage||'legacy';p.workflows||=['petrophysics'];}if(!portfolio.records.some(p=>p.id===portfolio.activeId))portfolio.activeId=null;}}catch{}try{const cloud=await repository.listCloud();if(loadedUid!==uid)return;for(const p of cloud){const index=portfolio.records.findIndex(r=>r.id===p.id);if(index>=0){const cached=portfolio.records[index];if(cached.pendingSave){saveStates.set(p.id,'Unsaved changes');continue;}portfolio.records[index]=p;}else portfolio.records.push(p);}}catch(error){toast(error.message);}for(const p of portfolio.records){rememberSnapshot(p);if(p.pendingSave)saveStates.set(p.id,'Unsaved changes');if(p.storage==='legacy')saveStates.set(p.id,'Choose storage');if(p.storage==='portable')saveStates.set(p.id,'Unsaved changes');}if(portfolio.activeId){const p=projectContext();try{const record=p.storage==='legacy'||p.pendingSave?{workspace:portfolio.contexts[p.id]}:await repository.load(p);if(loadedUid!==uid)return;state={...structuredClone(initial),...record.workspace,project:p.name};if(record.revision)p.revision=record.revision;portfolio.contexts[p.id]=structuredClone(state);}catch(error){saveStates.set(p.id,'Unsaved changes');state={...structuredClone(initial),...portfolio.contexts[p.id],project:p.name};toast(error.message);}}}wells=state.wellDrafts||[];search='';projectQuery='';}if(uid&&session.account?.display_name)state.preferences={...state.preferences,displayName:session.account.display_name};route=location.hash.slice(1)||'home';if($('#dialog').open)$('#dialog').close();render();}

const saveSnapshots=new Map(),saveStates=new Map(),saveConflicts=new Set();

let saveTimer,saveChain=Promise.resolve();

function projectStages(p){const selected=workflows(p);return selected.includes('petrophysics')?(selected.includes('seismic')?[...stages,['seismic','Seismic interpretation','Review survey evidence']]:stages):seismicStages;}

function snapshot(p){const copy={...p};delete copy.revision;delete copy.pendingSave;return JSON.stringify([copy,portfolio.contexts[p.id]||{}]);}

function rememberSnapshot(p){saveSnapshots.set(p.id,snapshot(p));}

function updateSaveIndicator(){const b=$('.save-indicator');if(b)b.textContent=saveStates.get(portfolio.activeId)||'Saved';}

function queueProjectSaves(){clearTimeout(saveTimer);for(const p of portfolio.records){if(snapshot(p)!==saveSnapshots.get(p.id)){p.pendingSave=true;saveStates.set(p.id,'Unsaved changes');}}updateSaveIndicator();saveTimer=setTimeout(()=>flushProjectSaves().catch(error=>toast(error.message)),600);}

function flushProjectSaves(){clearTimeout(saveTimer);const uid=session.user?.uid;saveChain=saveChain.catch(()=>{}).then(async()=>{for(const p of portfolio.records){if(uid!==session.user?.uid)return;if(snapshot(p)===saveSnapshots.get(p.id)&&!p.pendingSave)continue;if(p.storage==='legacy'){saveStates.set(p.id,'Choose storage');continue;}saveStates.set(p.id,'Saving…');updateSaveIndicator();const before=snapshot(p),context=structuredClone(portfolio.contexts[p.id]||freshProjectContext(p.name));try{const result=await repository.save(p,context);if(uid!==session.user?.uid)return;p.revision=result.revision||0;p.pendingSave=!!result.unsaved;saveStates.set(p.id,result.unsaved?'Unsaved changes':'Saved');saveSnapshots.set(p.id,before);if(!result.unsaved&&snapshot(p)!==before)queueProjectSaves();}catch(error){p.pendingSave=true;if(error.code==='project_conflict')saveConflicts.add(p.id);saveStates.set(p.id,'Save failed · retry');updateSaveIndicator();throw error;}finally{if(uid===session.user?.uid){try{localStorage.setItem(storageKey('stratax.projects.v2'),JSON.stringify(portfolio));}catch{}updateSaveIndicator();}}}});return saveChain;}

function conflictDialog(){const p=projectContext();modal('This project changed elsewhere',`<p>Your pending changes remain on this device. Download them before continuing, or retain a recovery copy and load the current cloud version.</p><div class="actions"><button id="conflict-export">Download pending project</button><button id="conflict-reload" class="primary">Keep recovery copy & reload</button></div>`);$('#conflict-export').onclick=()=>projectAction('export-workspace');$('#conflict-reload').onclick=async()=>{try{localStorage.setItem(storageKey('stratax.conflict.'+p.id),JSON.stringify({project:p,workspace:state}));const record=await repository.load(p);Object.assign(p,record.project,{revision:record.revision,pendingSave:false});state={...structuredClone(initial),...record.workspace};portfolio.contexts[p.id]=structuredClone(state);saveConflicts.delete(p.id);rememberSnapshot(p);saveStates.set(p.id,'Saved');localStorage.setItem(storageKey('stratax.projects.v2'),JSON.stringify(portfolio));$('#dialog').close();render();}catch(error){toast(error.message);}};}
function unavailablePage(title,message){return heading(title,message)+panel('Evidence required',`<div class="empty">${icon('logs')}<strong>No scientific results available</strong><p>Original sources and saved configurations remain available in this project.</p>${go('files','View source files')}</div>`);}

function bindProjectUI(){if(['data','collection','files','wells','documents'].includes(route))bindDataPage();bindSwitcher({portfolio,openProject,navigate,esc,icon});if(route==='overview'&&projectContext()?.coordinates)mountMap($('#overview-map'),projectContext().coordinates);if(route==='map'&&projectContext()?.coordinates)mountMap($('#project-map'),projectContext().coordinates);}

function blobDownload(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}

async function projectAction(action){try{if(action==='project-settings'){projectEditor(portfolio.activeId);return;}if(action==='save-project'){if(saveConflicts.has(portfolio.activeId)){conflictDialog();return;}if(projectContext()?.storage==='legacy'){projectEditor(portfolio.activeId);return;}if(projectContext()?.storage==='local')await repository.reconnect(portfolio.activeId);save();await flushProjectSaves();return;}if(action==='export-workspace'){const p=projectContext();const blob=await repository.exportPackage(p,state);blobDownload(p.name.replace(/[^\w-]/g,'_')+'.stratax.json',blob);if(p.storage==='portable'){saveStates.set(p.id,'Downloaded');p.pendingSave=false;rememberSnapshot(p);updateSaveIndicator();}return;}if(action==='import-package'){const input=document.createElement('input');input.type='file';input.accept='.json,.stratax';input.onchange=async()=>{try{await attachLocal(await repository.importPackage(input.files[0]));}catch(error){toast(error.message);}};input.click();return;}if(action==='open-local'){const record=await repository.openLocal();if(record?.error)throw record.error;if(record)await attachLocal(record);}}catch(error){if(error.name!=='AbortError')toast(error.message);}}

async function attachLocal(record){if(portfolio.records.some(p=>p.id===record.project.id&&p.storage==='cloud'))throw new Error('A cloud project with this identity already exists. Import a project package to create an independent copy.');const index=portfolio.records.findIndex(p=>p.id===record.project.id);if(index>=0)portfolio.records[index]=record.project;else portfolio.records.push(record.project);portfolio.contexts[record.project.id]=record.workspace;rememberSnapshot(record.project);await repository.save(record.project,record.workspace);portfolio.activeId=record.project.id;state={...structuredClone(initial),...record.workspace};saveStates.set(record.project.id,record.project.storage==='local'?'Saved':'Unsaved changes');localStorage.setItem(storageKey('stratax.projects.v2'),JSON.stringify(portfolio));navigate('overview');}

window.addEventListener('beforeunload',event=>{if([...saveStates.values()].some(s=>/Unsaved|Saving|failed/.test(s))){event.preventDefault();event.returnValue='';}});

configureData({getProject:projectContext,getState:()=>state,icon,modal,toast,save,flush:flushProjectSaves,render,navigate,download:blobDownload,reload:async()=>{const p=projectContext();if(p?.storage==='cloud'){const record=await repository.load(p);Object.assign(p,record.project,{revision:record.revision});const cached=state.ingestion;state={...structuredClone(initial),...record.workspace,ingestion:cached};portfolio.contexts[p.id]=structuredClone(state);wells=state.wellDrafts||[];rememberSnapshot(p);saveStates.set(p.id,'Saved');localStorage.setItem(storageKey('stratax.projects.v2'),JSON.stringify(portfolio));}}});
render();initializeAuth(restoreUserWorkspace);
